import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const z=JSON.parse('{"title":"丹青引赠曹霸将军","description":"","frontmatter":{"title":"丹青引赠曹霸将军","date":"2026-11-23T00:00:00.000Z","seq":20,"categories":["美文","唐诗三百首"],"collection":"《唐诗三百首 · 七言古诗》","tags":["唐诗三百首","唐"],"poem":true,"poem_quote":false,"author":"杜甫","source_book":"唐诗三百首"},"headers":[],"relativePath":"blogs/唐诗三百首·七言古诗/丹青引赠曹霸将军.md","filePath":"blogs/唐诗三百首·七言古诗/丹青引赠曹霸将军.md"}'),o={name:"blogs/唐诗三百首·七言古诗/丹青引赠曹霸将军.md"};function l(c,a,n,m,_,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="丹青引赠曹霸将军" tabindex="-1">丹青引赠曹霸将军 <a class="header-anchor" href="#丹青引赠曹霸将军" aria-label="Permalink to &quot;丹青引赠曹霸将军&quot;">​</a></h1><p class="poem-meta">唐 · 杜甫　·　七言古诗</p><div class="poem"><p class="poem-stanza">将军魏武之子孙，于今为庶为清门。</p><p class="poem-stanza">英雄割据虽已矣，文采风流今尚存。</p><p class="poem-stanza">学书初学卫夫人，但恨无过王右军。</p><p class="poem-stanza">丹青不知老将至，富贵于我如浮云。</p><p class="poem-stanza">开元之中常引见，承恩数上南薰殿。</p><p class="poem-stanza">凌烟功臣少颜色，将军下笔开生面。</p><p class="poem-stanza">良相头上进贤冠，猛将腰间大羽箭。</p><p class="poem-stanza">褒公鄂公毛发动，英姿飒爽来酣战。</p><p class="poem-stanza">先帝御马五花骢，画工如山貌不同。</p><p class="poem-stanza">是日牵来赤墀下，迥立阊阖生长风。</p><p class="poem-stanza">诏谓将军拂绢素，意匠惨澹经营中。</p><p class="poem-stanza">斯须九重真龙出，一洗万古凡马空。</p><p class="poem-stanza">玉花却在御榻上，榻上庭前屹相向。</p><p class="poem-stanza">至尊含笑催赐金，圉人太仆皆惆怅。</p><p class="poem-stanza">弟子韩干早入室，亦能画马穷殊相。</p><p class="poem-stanza">干惟画肉不画骨，忍使骅骝气凋丧。</p><p class="poem-stanza">将军画善盖有神，必逢佳士亦写真。</p><p class="poem-stanza">即今漂泊干戈际，屡貌寻常行路人。</p><p class="poem-stanza">途穷反遭俗眼白，世上未有如公贫。</p><p class="poem-stanza">但看古来盛名下，终日坎壈缠其身。</p></div>',3)])])}const d=s(o,[["render",l]]);export{z as __pageData,d as default};
